"""Generate test fixtures."""

import os
import json
import numpy as np
from scipy.integrate import quad

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)


def mgf(t, sigma):
    """
    Evaluate the MGF of a Rayleigh distribution by integrating its definition.

    The MGF is `E[exp(tX)] = ∫₀^∞ exp(t*x) * (x/σ²) * exp(-x²/(2σ²)) dx`.

    Integrating the definition numerically, rather than evaluating a closed
    form, keeps the fixtures independent of the formula being tested.

    # Arguments

    * `t`: input value.
    * `sigma`: scale parameter.

    # Returns

    Evaluated MGF.

    # Examples

    ```python
    python> mgf(0.0, 1.0)
    1.0
    ```
    """
    a = t * sigma
    var = sigma * sigma

    def integrand(x):
        return np.exp((t * x) - ((x * x) / (2.0 * var))) * (x / var)

    # The integrand peaks at `σ(a/2 + sqrt(a²/4 + 1))` and decays like a
    # Gaussian with standard deviation `σ`, so it is negligible forty standard
    # deviations beyond the peak:
    peak = sigma * ((a / 2.0) + np.sqrt(((a * a) / 4.0) + 1.0))
    upper = peak + (40.0 * sigma)
    val, _ = quad(integrand, 0.0, upper, points=[peak], limit=2000,
                    epsabs=0.0, epsrel=1e-13)
    return val


def gen(x, sigma, name):
    """
    Generate fixture data and write to file.

    # Arguments

    * `x`: input values.
    * `sigma`: scale parameters.
    * `name`: output filename.

    # Examples

    ```python
    python> x = np.random.uniform(-1.0, 1.0, 1000)
    python> sigma = np.random.uniform(0.0, 5.0, 1000)
    python> gen(x, sigma, "data.json")
    ```
    """
    z = np.array([mgf(x[i], sigma[i]) for i in range(len(x))])

    # Store data to be written to file as a dictionary:
    data = {
        "x": x.tolist(),
        "sigma": sigma.tolist(),
        "expected": z.tolist()
    }

    # Based on the script directory, create an output filepath:
    filepath = os.path.join(DIR, name)

    # Write the data to the output filepath as JSON:
    with open(filepath, "w", encoding='utf-8') as outfile:
        json.dump(data, outfile)

    # Include trailing newline:
    with open(filepath, "a", encoding='utf-8') as outfile:
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Small scale parameter:
    x = np.random.uniform(-5.0, 5.0, 1000)
    sigma = np.random.uniform(0.0, 1.0, 1000)
    gen(x, sigma, "small_scale.json")

    # Medium scale parameter:
    x = np.random.uniform(-2.0, 2.0, 1000)
    sigma = np.random.uniform(1.0, 5.0, 1000)
    gen(x, sigma, "medium_scale.json")

    # Large scale parameter:
    x = np.random.uniform(-1.0, 1.0, 1000)
    sigma = np.random.uniform(5.0, 20.0, 1000)
    gen(x, sigma, "large_scale.json")


if __name__ == "__main__":
    main()
